:root {
    /* Scale-specific absolute heights */
    --leading-4: 16px;
    --leading-5: 20px;
    --leading-6: 24px;
    --leading-8: 32px;

    /* Unitless proportional line-heights */
    --leading-none: 1; /* Resolves to 100% of the active font-size */
    --leading-tight: 1.25;
    --leading-snug: 1.375;
    --leading-normal: 1.5;
