    /// Outer boundary: Exclusively controls permit lifecycle, timeout, and cancellation
    pub async fn upload<R: tokio::io::AsyncRead + Send + Unpin>(
        &self,
        key: &str,
        reader: R,
        cancel: &tokio_util::sync::CancellationToken,
