    image.onerror = (error) => {
      if (isAborted) return;
      if (callbacksRef.current.onError) {
        callbacksRef.current.onError(error);
      }
      if (callbacksRef.current.onLoadEnd) {
        callbacksRef.current.onLoadEnd();
      }
    };

    image.src = uri;

