// BZIP2 polynomial: 0x04C11DB7 (MSB-first, non-reflected)
var bzip2Table = func() [256]uint32 {
	const poly = 0x04C11DB7
	var t [256]uint32
	for i := 0; i < 256; i++ {
		crc := uint32(i) << 24
		for j := 0; j < 8; j++ {
			if crc&0x80000000 != 0 {
				crc = (crc << 1) ^ poly
			} else {
				crc <<= 1
			}
		}
		t[i] = crc
	}
	return t
}()

