    if (this.pending === 0 && !this.isTerminated) {
      setTimeout(async () => {
        await this.queue.onIdle();
        if (this.pending === 0 && !this.isTerminated) {
          this.isTerminated = true;
          this.emit("end");
        }
      }, 100);
    }
  }

