            Component::ParentDir => {
                normalized_parts.pop();
            }
            Component::CurDir => {}
            normal_or_root => normalized_parts.push(normal_or_root),
        }
    }

    let resolved_path: PathBuf = normalized_parts.into_iter().collect();

    // Verify boundary confinement
    resolved_path.starts_with(repo_root)
}
